def next_power_of_2(n):
    if n <= 0:
        return 1
    if (n & (n - 1)) == 0:
        return n
    power = 1
    while power < n:
        power <<= 1
    return power

# Test cases
assert next_power_of_2(5) == 8
assert next_power_of_2(17) == 32

